UPDATE tbl_Volunteer
SET AccountStatus = #{accountStatus, jdbcType=NVARCHAR}
WHERE VolunteerID = #{volunteerId, jdbcType=CHAR}

UPDATE tbl_Volunteer
SET Password = #{newPassword}
WHERE VolunteerID = #{volunteerId}

mapper.select:
SELECT VolunteerID as volunteerId, Username as username, Name as name, PhoneNumber as phone, IDCardNumber as idCard, Password as password, Country as country, Gender as gender, ServiceArea as serviceArea, Ethnicity as ethnicity, PoliticalStatus as politicalStatus, HighestEducation as highestEducation, EmploymentStatus as employmentStatus, ServiceCategory as serviceCategory, TotalVolunteerHours as totalServiceHours, VolunteerRating as volunteerComprehensiveScore, AccountStatus as accountStatus FROM tbl_Volunteer
AND Name LIKE CONCAT('%', #{name}, '%') AND Username = #{username} AND ServiceCategory = #{serviceCategory}
ORDER BY VolunteerID DESC
